test('#98: not-in-fleet reads EVERY manifest — a consumer sorted ninth is still found', () => {
	const fx = fixture();
	try {
		const files = {};
		for (const d of ['a', 'b', 'c', 'd', 'e', 'f', 'g', 'h']) {
			files[`packages/${d}/package.json`] = JSON.stringify({ name: d });
		}
		files['packages/z/package.json'] = JSON.stringify({
			name: 'z',
			dependencies: { '@wolffm/themes': '^1.0.0' },
		});
		// Past the grace, so the finding is a failing one.
		const ts = new Date(Date.now() - 100 * 3_600_000).toISOString();
		makeRepo(join(fx.reposDir, 'repo-mono'), files, {
			GIT_AUTHOR_DATE: ts,
			GIT_COMMITTER_DATE: ts,
		});
		const { code, out } = run(fx);
		assert.deepEqual(rulesFor(JSON.parse(out), 'repo-mono'), ['not-in-fleet'], out);
		assert.equal(code, 1);
	} finally {
		cleanup(fx);
	}
});
